from __future__ import annotations

import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]


def read(path: str) -> str:
    return (ROOT / path).read_text(encoding="utf-8")


def write(path: str, value: str) -> None:
    destination = ROOT / path
    destination.parent.mkdir(parents=True, exist_ok=True)
    destination.write_text(value, encoding="utf-8")


def replace_once(value: str, old: str, new: str, *, label: str) -> str:
    count = value.count(old)
    if count != 1:
        raise RuntimeError(f"{label}: expected one match, found {count}")
    return value.replace(old, new, 1)


def patch_migrations() -> None:
    path = "services/api/src/finance_agent/storage/migrations.py"
    value = read(path)
    if 'name="workspace_data_control"' in value:
        return
    addition = r'''
    Migration(
        version=25,
        name="workspace_data_control",
        sql="""
        CREATE TABLE workspace_exports (
            artifact_id TEXT PRIMARY KEY,
            workspace_id TEXT NOT NULL REFERENCES workspaces(workspace_id),
            relative_path TEXT NOT NULL UNIQUE,
            content_hash TEXT NOT NULL CHECK (length(content_hash) = 64),
            size_bytes INTEGER NOT NULL CHECK (size_bytes > 0),
            manifest_json TEXT NOT NULL,
            generated_at TEXT NOT NULL,
            status TEXT NOT NULL CHECK (status IN ('available', 'pruned'))
        );

        CREATE TABLE data_retention_policies (
            workspace_id TEXT PRIMARY KEY REFERENCES workspaces(workspace_id),
            generated_export_days INTEGER NOT NULL CHECK (
                generated_export_days BETWEEN 1 AND 3650
            ),
            auto_prune_exports INTEGER NOT NULL CHECK (auto_prune_exports IN (0, 1)),
            updated_at TEXT NOT NULL
        );

        CREATE TABLE destructive_challenges (
            challenge_id TEXT PRIMARY KEY,
            workspace_id TEXT NOT NULL REFERENCES workspaces(workspace_id),
            action TEXT NOT NULL CHECK (action IN ('reset_demo', 'clear_workspace')),
            confirmation_hash TEXT NOT NULL CHECK (length(confirmation_hash) = 64),
            created_at TEXT NOT NULL,
            expires_at TEXT NOT NULL,
            used_at TEXT,
            CHECK (created_at < expires_at)
        );

        CREATE INDEX workspace_exports_workspace_generated
            ON workspace_exports(workspace_id, generated_at DESC, artifact_id DESC);
        CREATE INDEX destructive_challenges_expiry
            ON destructive_challenges(workspace_id, expires_at, used_at);
        """,
    ),
'''
    stripped = value.rstrip()
    if not stripped.endswith(")"):
        raise RuntimeError("migrations.py does not end with the migration tuple")
    write(path, stripped[:-1] + addition + ")\n")


def create_data_control() -> None:
    write(
        "services/api/src/finance_agent/privacy/__init__.py",
        '''from finance_agent.privacy.data_control import (\n    DestructiveChallenge, WorkspaceArchiveArtifact, WorkspaceDataControl,\n)\n\n__all__ = ["DestructiveChallenge", "WorkspaceArchiveArtifact", "WorkspaceDataControl"]\n''',
    )
    write(
        "services/api/src/finance_agent/privacy/data_control.py",
        '''"""Owner-controlled local data inventory, export, retention and destructive gates."""\n\nfrom __future__ import annotations\n\nimport hashlib\nimport hmac\nimport json\nimport os\nimport secrets\nimport zipfile\nfrom collections.abc import Callable\nfrom dataclasses import dataclass\nfrom datetime import UTC, datetime, timedelta\nfrom pathlib import Path\n\nfrom finance_agent.storage import SQLiteStore, canonical_json\nfrom finance_agent.storage.backup import DatabaseBackupService\n\n\n@dataclass(frozen=True, slots=True)\nclass WorkspaceArchiveArtifact:\n    artifact_id: str\n    content: bytes\n    content_hash: str\n    filename: str\n    generated_at: str\n    manifest: dict[str, object]\n\n    @property\n    def media_type(self) -> str:\n        return "application/zip"\n\n    def as_contract(self) -> dict[str, object]:\n        return {\n            "artifactId": self.artifact_id,\n            "filename": self.filename,\n            "contentHash": self.content_hash,\n            "sizeBytes": len(self.content),\n            "generatedAt": self.generated_at,\n            "manifest": self.manifest,\n        }\n\n\n@dataclass(frozen=True, slots=True)\nclass DestructiveChallenge:\n    challenge_id: str\n    workspace_id: str\n    action: str\n    confirmation: str\n    expires_at: str\n\n    def as_contract(self) -> dict[str, object]:\n        return {\n            "challengeId": self.challenge_id,\n            "workspaceId": self.workspace_id,\n            "action": self.action,\n            "confirmation": self.confirmation,\n            "expiresAt": self.expires_at,\n        }\n\n\ndef _stable_id(prefix: str, *parts: str) -> str:\n    return f"{prefix}_{hashlib.sha256(chr(0).join(parts).encode()).hexdigest()[:24]}"\n\n\nclass WorkspaceDataControl:\n    INVENTORY_TABLES = (\n        "source_items", "source_rows", "transactions", "conversation_turns",\n        "claims", "knowledge_owner_statements", "knowledge_documents",\n        "knowledge_entities", "knowledge_facts", "finance_events", "artifacts",\n        "accounting_exports", "model_runs", "egress_receipts", "work_receipts",\n    )\n\n    def __init__(\n        self,\n        store: SQLiteStore,\n        backups: DatabaseBackupService,\n        export_root: str | Path,\n        receipt_root: str | Path,\n        *,\n        clock: Callable[[], datetime] | None = None,\n    ) -> None:\n        self.store = store\n        self.backups = backups\n        self.export_root = Path(export_root).expanduser().resolve()\n        self.receipt_root = Path(receipt_root).expanduser().resolve()\n        self.clock = clock or (lambda: datetime.now(UTC))\n        for directory in (self.export_root, self.receipt_root):\n            directory.mkdir(parents=True, exist_ok=True)\n            try:\n                directory.chmod(0o700)\n            except OSError:\n                pass\n\n    def ensure_default(self, workspace_id: str) -> None:\n        if self.store.fetch_one(\n            "SELECT 1 FROM workspaces WHERE workspace_id = ?", (workspace_id,)\n        ) is None:\n            return\n        instant = self.clock().astimezone(UTC).isoformat()\n        with self.store.transaction() as connection:\n            connection.execute(\n                """\n                INSERT INTO data_retention_policies(\n                    workspace_id, generated_export_days, auto_prune_exports, updated_at\n                ) VALUES (?, 30, 0, ?)\n                ON CONFLICT(workspace_id) DO NOTHING\n                """,\n                (workspace_id, instant),\n            )\n\n    def inventory(self, workspace_id: str) -> dict[str, object]:\n        workspace = self.store.fetch_one(\n            "SELECT name, currency, timezone, data_through FROM workspaces WHERE workspace_id = ?",\n            (workspace_id,),\n        )\n        if workspace is None:\n            raise KeyError(workspace_id)\n        counts: dict[str, int] = {}\n        with self.store.connect() as connection:\n            available = {\n                str(row["name"])\n                for row in connection.execute(\n                    "SELECT name FROM sqlite_master WHERE type = 'table'"\n                )\n            }\n            for table in self.INVENTORY_TABLES:\n                if table not in available:\n                    counts[table] = 0\n                    continue\n                row = connection.execute(\n                    f'SELECT COUNT(*) AS count FROM "{table}" WHERE workspace_id = ?',\n                    (workspace_id,),\n                ).fetchone()\n                counts[table] = int(row["count"])\n        exports = self.store.fetch_all(\n            "SELECT status, COUNT(*) AS count FROM workspace_exports WHERE workspace_id = ? GROUP BY status",\n            (workspace_id,),\n        )\n        return {\n            "workspaceId": workspace_id,\n            "workspace": dict(workspace),\n            "recordCounts": counts,\n            "generatedExports": {str(row["status"]): int(row["count"]) for row in exports},\n            "databasePath": str(Path(self.store.database_path).resolve()),\n            "externalCredentialsStored": False,\n            "authoritativeLedger": False,\n        }\n\n    def _manifest(self, workspace_id: str, backup_path: Path, generated_at: str) -> dict[str, object]:\n        inventory = self.inventory(workspace_id)\n        backup_hash = hashlib.sha256(backup_path.read_bytes()).hexdigest()\n        artefacts = self.store.fetch_all(\n            """\n            SELECT artifact_id, kind, title, content_hash, generated_at\n            FROM artifacts WHERE workspace_id = ? AND is_current = 1\n            ORDER BY artifact_id\n            """,\n            (workspace_id,),\n        )\n        accounting = self.store.fetch_all(\n            """\n            SELECT artifact_id, kind, title, content_hash, generated_at\n            FROM accounting_exports WHERE workspace_id = ?\n            ORDER BY artifact_id\n            """,\n            (workspace_id,),\n        )\n        return {\n            "manifestVersion": "folio.workspace-export@1",\n            "workspaceId": workspace_id,\n            "generatedAt": generated_at,\n            "database": {\n                "archivePath": "workspace.sqlite3",\n                "sha256": backup_hash,\n                "sizeBytes": backup_path.stat().st_size,\n            },\n            "inventory": inventory,\n            "includedArtifacts": [dict(row) for row in (*artefacts, *accounting)],\n            "excluded": [\n                "process environment", "provider credentials", "session token",\n                "application logs outside the workspace database",\n            ],\n        }\n\n    def create_archive(self, workspace_id: str) -> WorkspaceArchiveArtifact:\n        now = self.clock().astimezone(UTC)\n        generated_at = now.isoformat()\n        backup = self.backups.create(workspace_id)\n        backup_path = (self.backups.backup_root / backup.relative_path).resolve()\n        if backup_path.parent != self.backups.backup_root:\n            raise RuntimeError("backup receipt escaped its configured root")\n        manifest = self._manifest(workspace_id, backup_path, generated_at)\n        seed = hashlib.sha256(canonical_json(manifest).encode()).hexdigest()\n        artifact_id = f"artifact_workspace_export_{seed[:20]}"\n        filename = f"folio-workspace-{workspace_id}-{now.strftime('%Y%m%dT%H%M%SZ')}.zip"\n        final_path = self.export_root / filename\n        temporary_path = self.export_root / f".{filename}.tmp"\n        with zipfile.ZipFile(temporary_path, "w", compression=zipfile.ZIP_DEFLATED) as archive:\n            archive.write(backup_path, "workspace.sqlite3")\n            archive.writestr("manifest.json", json.dumps(manifest, indent=2, sort_keys=True) + "\\n")\n            for row in self.store.fetch_all(\n                """\n                SELECT artifact_id, kind, content FROM artifacts\n                WHERE workspace_id = ? AND is_current = 1 ORDER BY artifact_id\n                """,\n                (workspace_id,),\n            ):\n                extension = "pdf" if str(row["kind"]).endswith("pdf") else "html"\n                archive.writestr(\n                    f"prepared/{row['artifact_id']}.{extension}", bytes(row["content"])\n                )\n            for row in self.store.fetch_all(\n                """\n                SELECT artifact_id, filename, content FROM accounting_exports\n                WHERE workspace_id = ? ORDER BY artifact_id\n                """,\n                (workspace_id,),\n            ):\n                archive.writestr(\n                    f"accounting/{Path(str(row['filename'])).name}", bytes(row["content"])\n                )\n        content = temporary_path.read_bytes()\n        digest = hashlib.sha256(content).hexdigest()\n        os.replace(temporary_path, final_path)\n        try:\n            final_path.chmod(0o600)\n        except OSError:\n            pass\n        relative_path = final_path.relative_to(self.export_root).as_posix()\n        with self.store.transaction() as connection:\n            connection.execute(\n                """\n                INSERT INTO workspace_exports(\n                    artifact_id, workspace_id, relative_path, content_hash, size_bytes,\n                    manifest_json, generated_at, status\n                ) VALUES (?, ?, ?, ?, ?, ?, ?, 'available')\n                ON CONFLICT(artifact_id) DO NOTHING\n                """,\n                (\n                    artifact_id, workspace_id, relative_path, digest, len(content),\n                    canonical_json(manifest), generated_at,\n                ),\n            )\n        return WorkspaceArchiveArtifact(\n            artifact_id=artifact_id, content=content, content_hash=digest,\n            filename=filename, generated_at=generated_at, manifest=manifest,\n        )\n\n    def get_artifact(self, artifact_id: str) -> WorkspaceArchiveArtifact:\n        row = self.store.fetch_one(\n            "SELECT * FROM workspace_exports WHERE artifact_id = ?", (artifact_id,)\n        )\n        if row is None:\n            raise KeyError(artifact_id)\n        if str(row["status"]) != "available":\n            raise ValueError("workspace export has been pruned")\n        path = (self.export_root / str(row["relative_path"])).resolve()\n        if path.parent != self.export_root or not path.is_file():\n            raise ValueError("workspace export file is unavailable")\n        content = path.read_bytes()\n        digest = hashlib.sha256(content).hexdigest()\n        if digest != str(row["content_hash"]):\n            raise ValueError("workspace export hash does not match its receipt")\n        return WorkspaceArchiveArtifact(\n            artifact_id=artifact_id, content=content, content_hash=digest,\n            filename=path.name, generated_at=str(row["generated_at"]),\n            manifest=json.loads(str(row["manifest_json"])),\n        )\n\n    def retention_policy(self, workspace_id: str) -> dict[str, object]:\n        row = self.store.fetch_one(\n            "SELECT * FROM data_retention_policies WHERE workspace_id = ?",\n            (workspace_id,),\n        )\n        if row is None:\n            raise KeyError(workspace_id)\n        return {\n            "workspaceId": workspace_id,\n            "generatedExportDays": int(row["generated_export_days"]),\n            "autoPruneExports": bool(row["auto_prune_exports"]),\n            "updatedAt": str(row["updated_at"]),\n        }\n\n    def configure_retention(\n        self, workspace_id: str, *, generated_export_days: int,\n        auto_prune_exports: bool\n    ) -> dict[str, object]:\n        if generated_export_days < 1 or generated_export_days > 3650:\n            raise ValueError("generated export retention must be between 1 and 3650 days")\n        instant = self.clock().astimezone(UTC).isoformat()\n        with self.store.transaction() as connection:\n            updated = connection.execute(\n                """\n                UPDATE data_retention_policies\n                SET generated_export_days = ?, auto_prune_exports = ?, updated_at = ?\n                WHERE workspace_id = ?\n                """,\n                (generated_export_days, int(auto_prune_exports), instant, workspace_id),\n            )\n            if updated.rowcount != 1:\n                raise KeyError(workspace_id)\n        return self.retention_policy(workspace_id)\n\n    def apply_retention(self, workspace_id: str) -> dict[str, object]:\n        policy = self.retention_policy(workspace_id)\n        if not bool(policy["autoPruneExports"]):\n            return {"workspaceId": workspace_id, "status": "disabled", "prunedArtifactIds": []}\n        cutoff = self.clock().astimezone(UTC) - timedelta(\n            days=int(policy["generatedExportDays"])\n        )\n        rows = self.store.fetch_all(\n            """\n            SELECT artifact_id, relative_path FROM workspace_exports\n            WHERE workspace_id = ? AND status = 'available' AND generated_at < ?\n            ORDER BY generated_at, artifact_id\n            """,\n            (workspace_id, cutoff.isoformat()),\n        )\n        pruned: list[str] = []\n        for row in rows:\n            path = (self.export_root / str(row["relative_path"])).resolve()\n            if path.parent == self.export_root:\n                path.unlink(missing_ok=True)\n            pruned.append(str(row["artifact_id"]))\n        if pruned:\n            with self.store.transaction() as connection:\n                connection.executemany(\n                    "UPDATE workspace_exports SET status = 'pruned' WHERE artifact_id = ?",\n                    [(artifact_id,) for artifact_id in pruned],\n                )\n        return {"workspaceId": workspace_id, "status": "completed", "prunedArtifactIds": pruned}\n\n    def issue_challenge(self, workspace_id: str, action: str) -> DestructiveChallenge:\n        if action not in {"reset_demo", "clear_workspace"}:\n            raise ValueError("unsupported destructive action")\n        if self.store.fetch_one(\n            "SELECT 1 FROM workspaces WHERE workspace_id = ?", (workspace_id,)\n        ) is None:\n            raise KeyError(workspace_id)\n        now = self.clock().astimezone(UTC)\n        nonce = secrets.token_hex(4).upper()\n        verb = "RESET" if action == "reset_demo" else "CLEAR"\n        confirmation = f"CONFIRM-{verb}-{nonce}"\n        challenge_id = _stable_id(\n            "destructive", workspace_id, action, now.isoformat(), nonce\n        )\n        expires = now + timedelta(minutes=5)\n        with self.store.transaction() as connection:\n            connection.execute(\n                """\n                INSERT INTO destructive_challenges(\n                    challenge_id, workspace_id, action, confirmation_hash,\n                    created_at, expires_at, used_at\n                ) VALUES (?, ?, ?, ?, ?, ?, NULL)\n                """,\n                (\n                    challenge_id, workspace_id, action,\n                    hashlib.sha256(confirmation.encode()).hexdigest(),\n                    now.isoformat(), expires.isoformat(),\n                ),\n            )\n        return DestructiveChallenge(\n            challenge_id=challenge_id, workspace_id=workspace_id, action=action,\n            confirmation=confirmation, expires_at=expires.isoformat(),\n        )\n\n    def consume_challenge(\n        self, workspace_id: str, action: str, challenge_id: str, confirmation: str\n    ) -> None:\n        now = self.clock().astimezone(UTC)\n        with self.store.transaction() as connection:\n            row = connection.execute(\n                "SELECT * FROM destructive_challenges WHERE challenge_id = ?",\n                (challenge_id,),\n            ).fetchone()\n            if row is None:\n                raise ValueError("destructive challenge is unknown")\n            if str(row["workspace_id"]) != workspace_id or str(row["action"]) != action:\n                raise ValueError("destructive challenge does not match this request")\n            if row["used_at"] is not None:\n                raise ValueError("destructive challenge has already been used")\n            if datetime.fromisoformat(str(row["expires_at"])) <= now:\n                raise ValueError("destructive challenge has expired")\n            supplied = hashlib.sha256(confirmation.encode()).hexdigest()\n            if not hmac.compare_digest(supplied, str(row["confirmation_hash"])):\n                raise ValueError("destructive confirmation text does not match")\n            connection.execute(\n                "UPDATE destructive_challenges SET used_at = ? WHERE challenge_id = ?",\n                (now.isoformat(), challenge_id),\n            )\n\n    def write_destructive_receipt(\n        self, *, workspace_id: str, action: str, challenge_id: str,\n        archive: WorkspaceArchiveArtifact\n    ) -> Path:\n        occurred_at = self.clock().astimezone(UTC).isoformat()\n        payload = {\n            "receiptVersion": "folio.destructive-action@1",\n            "workspaceId": workspace_id,\n            "action": action,\n            "challengeId": challenge_id,\n            "recoveryArchive": {\n                "artifactId": archive.artifact_id,\n                "filename": archive.filename,\n                "contentHash": archive.content_hash,\n            },\n            "occurredAt": occurred_at,\n        }\n        encoded = canonical_json(payload).encode()\n        receipt_hash = hashlib.sha256(encoded).hexdigest()\n        path = self.receipt_root / f"destructive-{receipt_hash[:24]}.json"\n        temporary = path.with_suffix(".tmp")\n        temporary.write_bytes(encoded + b"\\n")\n        os.replace(temporary, path)\n        try:\n            path.chmod(0o600)\n        except OSError:\n            pass\n        return path\n''',
    )


def patch_route_protocol() -> None:
    path = "services/api/src/finance_agent/api/routes/dependencies.py"
    value = read(path)
    anchor = """    async def accounting_profile(self, workspace_id: str) -> Mapping[str, object]: ...\n"""
    methods = """    async def data_inventory(self, workspace_id: str) -> Mapping[str, object]: ...\n\n    async def create_workspace_export(self, workspace_id: str) -> Mapping[str, object]: ...\n\n    async def retention_policy(self, workspace_id: str) -> Mapping[str, object]: ...\n\n    async def configure_retention(\n        self, *, workspace_id: str, generated_export_days: int,\n        auto_prune_exports: bool\n    ) -> Mapping[str, object]: ...\n\n    async def apply_retention(self, workspace_id: str) -> Mapping[str, object]: ...\n\n    async def issue_destructive_challenge(\n        self, *, workspace_id: str, action: str\n    ) -> Mapping[str, object]: ...\n\n    async def execute_destructive_action(\n        self, *, workspace_id: str, action: str, challenge_id: str, confirmation: str\n    ) -> Mapping[str, object]: ...\n\n"""
    if anchor not in value:
        raise RuntimeError("accounting protocol anchor is missing")
    write(path, value.replace(anchor, methods + anchor, 1))


def patch_routes() -> None:
    path = "services/api/src/finance_agent/api/routes/router.py"
    value = read(path)
    request_anchor = """class AccountingProfileRequest(RequestModel):\n"""
    models = """class RetentionPolicyRequest(RequestModel):\n    workspace_id: str = Field(alias=\"workspaceId\")\n    generated_export_days: int = Field(alias=\"generatedExportDays\", ge=1, le=3650)\n    auto_prune_exports: bool = Field(alias=\"autoPruneExports\")\n\n\nclass DestructiveChallengeRequest(RequestModel):\n    workspace_id: str = Field(alias=\"workspaceId\")\n    action: str = Field(pattern=r\"^(reset_demo|clear_workspace)$\")\n\n\nclass DestructiveExecuteRequest(DestructiveChallengeRequest):\n    challenge_id: str = Field(alias=\"challengeId\")\n    confirmation: str = Field(min_length=1, max_length=160)\n\n\n"""
    if request_anchor not in value:
        raise RuntimeError("accounting request anchor is missing")
    value = value.replace(request_anchor, models + request_anchor, 1)

    route_anchor = '''    @router.get("/v1/accounting/profile")\n'''
    routes = '''    @router.get("/v1/data/inventory")\n    async def data_inventory(\n        services: Services,\n        workspace_id: Annotated[str, Query(alias="workspaceId")],\n    ) -> dict[str, object]:\n        return dict(await services.data_inventory(workspace_id))\n\n    @router.post("/v1/data/exports", status_code=201)\n    async def create_workspace_export(\n        body: SchedulerTickRequest,\n        services: Services,\n    ) -> dict[str, object]:\n        return dict(await services.create_workspace_export(body.workspace_id))\n\n    @router.get("/v1/data/retention")\n    async def retention_policy(\n        services: Services,\n        workspace_id: Annotated[str, Query(alias="workspaceId")],\n    ) -> dict[str, object]:\n        return dict(await services.retention_policy(workspace_id))\n\n    @router.put("/v1/data/retention")\n    async def configure_retention(\n        body: RetentionPolicyRequest,\n        services: Services,\n    ) -> dict[str, object]:\n        return dict(\n            await services.configure_retention(\n                workspace_id=body.workspace_id,\n                generated_export_days=body.generated_export_days,\n                auto_prune_exports=body.auto_prune_exports,\n            )\n        )\n\n    @router.post("/v1/data/retention/apply")\n    async def apply_retention(\n        body: SchedulerTickRequest,\n        services: Services,\n    ) -> dict[str, object]:\n        return dict(await services.apply_retention(body.workspace_id))\n\n    @router.post("/v1/data/destructive-challenges", status_code=201)\n    async def issue_destructive_challenge(\n        body: DestructiveChallengeRequest,\n        services: Services,\n    ) -> dict[str, object]:\n        return dict(\n            await services.issue_destructive_challenge(\n                workspace_id=body.workspace_id, action=body.action\n            )\n        )\n\n    @router.post("/v1/data/destructive-actions")\n    async def execute_destructive_action(\n        body: DestructiveExecuteRequest,\n        services: Services,\n    ) -> dict[str, object]:\n        return dict(\n            await services.execute_destructive_action(\n                workspace_id=body.workspace_id, action=body.action,\n                challenge_id=body.challenge_id, confirmation=body.confirmation,\n            )\n        )\n\n'''
    if route_anchor not in value:
        raise RuntimeError("accounting route anchor is missing")
    write(path, value.replace(route_anchor, routes + route_anchor, 1))


def patch_services() -> None:
    path = "services/api/src/finance_agent/api/services.py"
    value = read(path)
    value = replace_once(
        value,
        "from finance_agent.models.router import ModelModeRouter\n",
        "from finance_agent.models.router import ModelModeRouter\nfrom finance_agent.privacy import WorkspaceDataControl\n",
        label="data control import",
    )
    value = replace_once(
        value,
        """        self.backups = DatabaseBackupService(self.store, backup_root)\n""",
        """        self.backups = DatabaseBackupService(self.store, backup_root)\n        self.data_control = WorkspaceDataControl(\n            self.store, self.backups,\n            Path(self.store.database_path).resolve().parent / \"exports\",\n            Path(self.store.database_path).resolve().parent / \"destructive-receipts\",\n        )\n""",
        label="data control composition",
    )
    value = replace_once(
        value,
        """        self.accounting.ensure_default(WORKSPACE_ID)\n""",
        """        self.accounting.ensure_default(WORKSPACE_ID)\n        self.data_control.ensure_default(WORKSPACE_ID)\n        self.workspace_deleted = False\n""",
        label="data control defaults",
    )

    health_old = '''    async def health(self) -> Mapping[str, object]:\n        database_ready = self.store.fetch_one("SELECT 1 AS ready") is not None\n        return {\n            "status": "ready" if database_ready else "degraded",\n'''
    health_new = '''    async def health(self) -> Mapping[str, object]:\n        database_ready = self.store.fetch_one("SELECT 1 AS ready") is not None\n        workspace_ready = self.store.fetch_one(\n            "SELECT 1 AS ready FROM workspaces WHERE workspace_id = ?", (WORKSPACE_ID,)\n        ) is not None\n        status = (\n            "ready" if database_ready and workspace_ready\n            else "awaiting_onboarding" if database_ready\n            else "degraded"\n        )\n        return {\n            "status": status,\n'''
    value = replace_once(value, health_old, health_new, label="health after clear")

    reset_anchor = '''    async def reset_demo(self, workspace_id: str) -> Mapping[str, object]:\n'''
    helper = '''    def _workspace_is_sealed_demo(self) -> bool:\n        rows = self.store.fetch_all(\n            "SELECT source_item_id, source_type FROM source_items WHERE workspace_id = ?",\n            (WORKSPACE_ID,),\n        )\n        if not rows:\n            return True\n        for row in rows:\n            source_type = str(row["source_type"])\n            source_id = str(row["source_item_id"])\n            if source_type == "csv" and source_id != "src_koru_bank_csv_20260717":\n                return False\n            if source_type not in {\n                "csv", "telegram_fixture", "akahu_fixture", "plaid_fixture"\n            }:\n                return False\n        return True\n\n'''
    if reset_anchor not in value:
        raise RuntimeError("reset_demo service anchor is missing")
    value = value.replace(reset_anchor, helper + reset_anchor, 1)
    value = replace_once(
        value,
        """        if workspace_id != WORKSPACE_ID:\n            raise KeyError(workspace_id)\n        async with self._lock:\n            imported = self.engine.reset_demo(DEMO_CSV)\n""",
        """        if workspace_id != WORKSPACE_ID:\n            raise KeyError(workspace_id)\n        if not self._workspace_is_sealed_demo():\n            raise ValueError(\n                \"This workspace contains owner-imported data. Use the challenged reset flow.\"\n            )\n        async with self._lock:\n            imported = self.engine.reset_demo(DEMO_CSV)\n""",
        label="protect demo reset",
    )

    anchor = """    async def accounting_profile(self, workspace_id: str) -> Mapping[str, object]:\n"""
    methods = '''    async def data_inventory(self, workspace_id: str) -> Mapping[str, object]:\n        if workspace_id != WORKSPACE_ID:\n            raise KeyError(workspace_id)\n        return await asyncio.to_thread(self.data_control.inventory, workspace_id)\n\n    async def create_workspace_export(self, workspace_id: str) -> Mapping[str, object]:\n        if workspace_id != WORKSPACE_ID:\n            raise KeyError(workspace_id)\n        async with self._lock:\n            artifact = await asyncio.to_thread(self.data_control.create_archive, workspace_id)\n        return artifact.as_contract()\n\n    async def retention_policy(self, workspace_id: str) -> Mapping[str, object]:\n        if workspace_id != WORKSPACE_ID:\n            raise KeyError(workspace_id)\n        return self.data_control.retention_policy(workspace_id)\n\n    async def configure_retention(\n        self, *, workspace_id: str, generated_export_days: int,\n        auto_prune_exports: bool\n    ) -> Mapping[str, object]:\n        if workspace_id != WORKSPACE_ID:\n            raise KeyError(workspace_id)\n        return self.data_control.configure_retention(\n            workspace_id, generated_export_days=generated_export_days,\n            auto_prune_exports=auto_prune_exports,\n        )\n\n    async def apply_retention(self, workspace_id: str) -> Mapping[str, object]:\n        if workspace_id != WORKSPACE_ID:\n            raise KeyError(workspace_id)\n        async with self._lock:\n            return await asyncio.to_thread(self.data_control.apply_retention, workspace_id)\n\n    async def issue_destructive_challenge(\n        self, *, workspace_id: str, action: str\n    ) -> Mapping[str, object]:\n        if workspace_id != WORKSPACE_ID:\n            raise KeyError(workspace_id)\n        return self.data_control.issue_challenge(workspace_id, action).as_contract()\n\n    async def execute_destructive_action(\n        self, *, workspace_id: str, action: str, challenge_id: str, confirmation: str\n    ) -> Mapping[str, object]:\n        if workspace_id != WORKSPACE_ID:\n            raise KeyError(workspace_id)\n        async with self._lock:\n            self.data_control.consume_challenge(\n                workspace_id, action, challenge_id, confirmation\n            )\n            archive = await asyncio.to_thread(\n                self.data_control.create_archive, workspace_id\n            )\n            receipt_path = self.data_control.write_destructive_receipt(\n                workspace_id=workspace_id, action=action,\n                challenge_id=challenge_id, archive=archive,\n            )\n            if action == "reset_demo":\n                imported = self.engine.reset_demo(DEMO_CSV)\n                self.event_buffer.clear()\n                self.current_mode = ModelMode.LOCAL\n                self._compose_controller()\n                self._initialise_frame()\n                self.working_understanding.ensure_current(workspace_id=WORKSPACE_ID)\n                self.scheduler.ensure_default(WORKSPACE_ID)\n                self.accounting.ensure_default(WORKSPACE_ID)\n                self.data_control.ensure_default(WORKSPACE_ID)\n                self.workspace_deleted = False\n                return {\n                    "workspaceId": workspace_id, "status": "reset",\n                    "sourceSha256": imported.source_sha256,\n                    "recoveryArchive": archive.as_contract(),\n                    "receiptPath": str(receipt_path),\n                }\n            self.store.recreate()\n            self.event_buffer.clear()\n            self.workspace_deleted = True\n            return {\n                "workspaceId": workspace_id, "status": "cleared",\n                "recoveryArchive": archive.as_contract(),\n                "receiptPath": str(receipt_path),\n                "nextAction": "restart_and_onboard",\n            }\n\n'''
    if anchor not in value:
        raise RuntimeError("accounting service method anchor is missing")
    value = value.replace(anchor, methods + anchor, 1)

    artifact_old = '''        if artifact_id.startswith("artifact_accounting_"):\n            value = self.accounting.get_artifact(artifact_id)\n            return ArtifactPayload(\n                content=value.content, media_type=value.media_type,\n                filename=value.filename, content_hash=value.content_hash,\n            )\n'''
    artifact_new = artifact_old + '''        if artifact_id.startswith("artifact_workspace_export_"):\n            value = self.data_control.get_artifact(artifact_id)\n            return ArtifactPayload(\n                content=value.content, media_type=value.media_type,\n                filename=value.filename, content_hash=value.content_hash,\n            )\n'''
    value = replace_once(value, artifact_old, artifact_new, label="workspace export delivery")
    write(path, value)


def patch_electron_artifacts() -> None:
    path = "apps/desktop/src/main/main.ts"
    value = read(path)
    value = replace_once(
        value,
        '''        : mediaType === "application/json"\n          ? "json"\n          : null;\n''',
        '''        : mediaType === "application/json"\n          ? "json"\n          : mediaType === "application/zip"\n            ? "zip"\n            : null;\n''',
        label="workspace archive media type",
    )
    value = replace_once(
        value,
        '      Accept: "application/pdf,text/html,text/csv,application/json",\n',
        '      Accept: "application/pdf,text/html,text/csv,application/json,application/zip",\n',
        label="workspace archive accept header",
    )
    write(path, value)


def add_docs() -> None:
    write(
        "docs/DATA_CONTROL.md",
        '''# Folio local data control\n\nFolio keeps the owner in control of local financial records.\n\n- **Inventory** reports the local record classes and counts without exposing provider credentials.\n- **Workspace export** creates a verified SQLite backup, a manifest and prepared artefacts in one content-hashed ZIP archive.\n- **Retention** applies only to generated export copies. Source transactions, evidence and owner statements are never silently expired.\n- **Reset and clear** require a short-lived one-time challenge. Folio creates a recovery archive and an external receipt before changing the live database.\n- **Clear** empties the live workspace and requires onboarding after restart. The explicitly disclosed recovery archive remains because preservation is safer than irreversible deletion. Owners can separately remove that archive through their operating system.\n\nProvider tokens, process environment, session tokens and unrelated logs are excluded from workspace archives.\n''',
    )


def add_tests() -> None:
    write(
        "services/api/tests/privacy/test_data_control.py",
        '''from __future__ import annotations\n\nimport hashlib\nimport zipfile\nfrom datetime import UTC, datetime, timedelta\nfrom pathlib import Path\n\nimport pytest\n\nfrom finance_agent.api.services import LocalRouteServices\nfrom finance_agent.finance import FinanceEngine\nfrom finance_agent.privacy import WorkspaceDataControl\nfrom finance_agent.storage import SQLiteStore\nfrom finance_agent.storage.backup import DatabaseBackupService\n\nROOT = Path(__file__).resolve().parents[4]\nCSV = ROOT / "fixtures" / "demo" / "koru-studio-bank-2026-07.csv"\n\n\ndef seeded(tmp_path: Path, clock=None):\n    store = SQLiteStore(tmp_path / "live" / "folio.sqlite3")\n    engine = FinanceEngine(store)\n    engine.reset_demo(CSV)\n    backups = DatabaseBackupService(store, tmp_path / "backups", clock=clock)\n    control = WorkspaceDataControl(\n        store, backups, tmp_path / "exports", tmp_path / "receipts", clock=clock\n    )\n    control.ensure_default("ws_koru_studio")\n    return store, engine, control\n\n\ndef test_workspace_archive_contains_verified_database_and_no_process_secrets(tmp_path: Path) -> None:\n    instant = datetime(2026, 8, 27, 6, 0, tzinfo=UTC)\n    _store, _engine, control = seeded(tmp_path, clock=lambda: instant)\n    artifact = control.create_archive("ws_koru_studio")\n    assert hashlib.sha256(artifact.content).hexdigest() == artifact.content_hash\n    archive_path = tmp_path / "archive.zip"\n    archive_path.write_bytes(artifact.content)\n    with zipfile.ZipFile(archive_path) as archive:\n        names = set(archive.namelist())\n        assert "workspace.sqlite3" in names\n        assert "manifest.json" in names\n        combined = b"".join(archive.read(name) for name in names if name.endswith((".json", ".html", ".csv")))\n        assert b"FOLIO_SESSION_TOKEN" not in combined\n        assert b"OPENAI_API_KEY" not in combined\n    assert artifact.manifest["excluded"]\n\n\ndef test_destructive_challenge_is_exact_expiring_and_one_time(tmp_path: Path) -> None:\n    instant = datetime(2026, 8, 27, 7, 0, tzinfo=UTC)\n    now = [instant]\n    _store, _engine, control = seeded(tmp_path, clock=lambda: now[0])\n    challenge = control.issue_challenge("ws_koru_studio", "reset_demo")\n    with pytest.raises(ValueError, match="does not match"):\n        control.consume_challenge(\n            "ws_koru_studio", "reset_demo", challenge.challenge_id, "WRONG"\n        )\n    control.consume_challenge(\n        "ws_koru_studio", "reset_demo", challenge.challenge_id, challenge.confirmation\n    )\n    with pytest.raises(ValueError, match="already been used"):\n        control.consume_challenge(\n            "ws_koru_studio", "reset_demo", challenge.challenge_id, challenge.confirmation\n        )\n    expired = control.issue_challenge("ws_koru_studio", "clear_workspace")\n    now[0] = instant + timedelta(minutes=6)\n    with pytest.raises(ValueError, match="expired"):\n        control.consume_challenge(\n            "ws_koru_studio", "clear_workspace", expired.challenge_id, expired.confirmation\n        )\n\n\ndef test_retention_prunes_only_generated_exports(tmp_path: Path) -> None:\n    instants = iter([\n        datetime(2026, 1, 1, tzinfo=UTC),\n        datetime(2026, 1, 1, tzinfo=UTC),\n        datetime(2026, 3, 1, tzinfo=UTC),\n        datetime(2026, 3, 1, tzinfo=UTC),\n    ])\n    store, _engine, control = seeded(tmp_path, clock=lambda: next(instants))\n    artifact = control.create_archive("ws_koru_studio")\n    source_count = len(store.fetch_all("SELECT * FROM source_rows"))\n    control.configure_retention(\n        "ws_koru_studio", generated_export_days=30, auto_prune_exports=True\n    )\n    result = control.apply_retention("ws_koru_studio")\n    assert artifact.artifact_id in result["prunedArtifactIds"]\n    assert len(store.fetch_all("SELECT * FROM source_rows")) == source_count\n    with pytest.raises(ValueError, match="pruned"):\n        control.get_artifact(artifact.artifact_id)\n\n\n@pytest.mark.asyncio\nasync def test_challenged_clear_creates_recovery_before_emptying_live_workspace(tmp_path: Path) -> None:\n    services = LocalRouteServices(tmp_path / "service" / "folio.sqlite3", auto_seed=True)\n    challenge = await services.issue_destructive_challenge(\n        workspace_id="ws_koru_studio", action="clear_workspace"\n    )\n    result = await services.execute_destructive_action(\n        workspace_id="ws_koru_studio", action="clear_workspace",\n        challenge_id=str(challenge["challengeId"]),\n        confirmation=str(challenge["confirmation"]),\n    )\n    assert result["status"] == "cleared"\n    assert Path(str(result["receiptPath"])).is_file()\n    recovery = result["recoveryArchive"]\n    recovery_path = (services.data_control.export_root / str(recovery["filename"]))\n    assert recovery_path.is_file()\n    assert services.store.fetch_one("SELECT 1 FROM workspaces") is None\n    assert (await services.health())["status"] == "awaiting_onboarding"\n    await services.aclose()\n\n\n@pytest.mark.asyncio\nasync def test_ordinary_demo_reset_refuses_owner_imported_data(tmp_path: Path) -> None:\n    services = LocalRouteServices(tmp_path / "reset" / "folio.sqlite3", auto_seed=True)\n    custom = CSV.read_bytes().replace(b"Acme", b"Owner")\n    await services.ingest_csv(\n        workspace_id="ws_koru_studio", filename="owner.csv", content=custom\n    )\n    with pytest.raises(ValueError, match="challenged reset flow"):\n        await services.reset_demo("ws_koru_studio")\n    await services.aclose()\n''',
    )


def main() -> None:
    patch_migrations()
    create_data_control()
    patch_route_protocol()
    patch_routes()
    patch_services()
    patch_electron_artifacts()
    add_docs()
    add_tests()


if __name__ == "__main__":
    main()
